size_t map_size = huffman_codes.size();
outfile.write(reinterpret_cast<const char*>(&map_size), sizeof(size_t));

for (const auto& pair : huffman_codes) {
    unsigned char ch = pair.first;
    std::string code = pair.second;
    size_t code_len = code.length();

    outfile.write(reinterpret_cast<const char*>(&ch), sizeof(unsigned char));
    outfile.write(reinterpret_cast<const char*>(&code_len), sizeof(size_t));

    // Write the binary representation of the code string
    // Since the code is a string of '0's and '1's, we store it as a string
    outfile.write(code.c_str(), code_len);
}

